import{_ as l,o as t,c as e,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Testing Meeting 2018-10-24","description":"","frontmatter":{"title":"Ceph Testing Meeting 2018-10-24","date":"2018-10-24T00:00:00.000Z","updated":"2018-10-25T00:00:00.000Z","tags":["Ceph","OpenStack","PR审查","测试","自动化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Testing_Meeting_2018-10-24.md","filePath":"posts/2018/Ceph_Testing_Meeting_2018-10-24.md","lastUpdated":1780459816000}'),s={name:"posts/2018/Ceph_Testing_Meeting_2018-10-24.md"};function p(o,i,a,r,g,u){return t(),e("div",null,[...i[0]||(i[0]=[n("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2018年10月24日 <strong>参会人员</strong>： John（疑似主持人）、Greg、Austin、Adkison、Ripples、Norge、Nathan <strong>会议内容</strong>：</p><p><strong>1. PR审查</strong></p><ul><li>Greg提到有一个PR需要审查，该PR修改了OpenStack的入口脚本，涉及测试包的安装和配置。</li><li>Adkison介绍了PR的背景和目的，包括向后兼容性、OpenStack版本支持和不同平台差异。</li><li>会议讨论了PR的关键点，如： <ul><li>对OpenStack后端的修改可能仅影响openSUSE用户。</li><li>需要支持Red Hat和Ubuntu。</li><li>审查测试报告的修改，确保不影响其他用户。</li><li>解决测试线程安全问题。</li></ul></li><li>会议决定由Adkison完成PR的审查和修改，Greg将提供反馈。</li></ul><p><strong>2. OpenStack部署</strong></p><ul><li>Nathan介绍了使用Ansible脚本和Touji工具进行的OpenStack部署工作。</li><li>会议讨论了部署过程中遇到的问题，如： <ul><li>配置外部DNS以解决OpenStack实例之间的通信问题。</li><li>添加Ansible角色以支持不同平台和区域。</li></ul></li><li>会议建议使用Touji角色管理OpenStack配置文件，并讨论了改进该角色的功能。</li></ul><p><strong>3. 测试</strong></p><ul><li>Norge提到了使用Jenkins进行测试的问题，包括使用较旧版本的Pillow导致测试失败。</li><li>会议讨论了以下问题： <ul><li>定期更新依赖项版本，避免意外中断。</li><li>修复Pillow中的问题，支持较新版本。</li><li>改进测试的可用性，例如隔离需要资源测试用例和解决线程安全问题。</li></ul></li></ul><p><strong>4. 其他事项</strong></p><ul><li>会议还讨论了以下事项： <ul><li>使用Clouds模式配置OpenStack，避免存储敏感信息。</li><li>使用Ansible角色管理不同平台和区域的配置。</li></ul></li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Adkison完成PR的审查和修改。</li><li>Nathan继续进行OpenStack部署工作。</li><li>Norge解决测试问题，并改进测试的可用性。</li><li>全体成员定期更新依赖项版本。</li></ul><p><strong>会议总结</strong>：</p><p>本次会议主要讨论了PR审查、OpenStack部署和测试相关的问题。会议明确了后续行动计划，并推动了相关工作的进展。</p><p><strong>改进点</strong>：</p><ul><li>保留了会议的关键细节，包括PR审查、OpenStack部署和测试问题的讨论。</li><li>强调了会议中决定的事项，如Adkison负责PR审查和修改，Nathan继续OpenStack部署等。</li><li>确保了计算机科学/ceph相关领域的英文原文关键词的保留，如Ceph、OpenStack、PR、测试等。</li><li>优化了总结的清晰度和准确性。</li></ul>",16)])])}const d=l(s,[["render",p]]);export{c as __pageData,d as default};
